// repair 1: saturate the increment at k (the I6 witness had x == k)
procedure clamp_ok(x: int, k: int)
  requires k >= 1 && x >= -k && x <= k
{
  var y: int;
  y := x;
  assert y >= -k && y <= k;
}

procedure clamp_step(x: int, k: int)
  requires k >= 1 && x >= -k && x <= k
{
  var y: int;
  y := x;
  y := (if x + 1 > k then k else x + 1);
  assert y <= k;
}

